using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using DevelApp.StepLexer;
using DevelApp.StepParser;
using DevelApp.StepParser.Tests;

namespace DevelApp.Benchmarks
{
    /// <summary>
    /// Measurement mode for issue #101 (incremental-parsing-ides article).
    /// Invoked via <c>--measure-issue101 &lt;outDir&gt;</c>.
    ///
    /// Workloads: committed corpus <c>Corpus/issue-101/cs-{100,500,2000,5000}.txt</c>
    /// (C#-like source, generated by the committed <c>gen_corpus.py</c>) lexed
    /// with the real CSharp10 grammar from Minotaur-Grammars; four committed
    /// deterministic edit traces (<c>traces/*.json</c>: char insert, word
    /// completion, line insertion, block paste).
    ///
    /// Configurations compared per (size, trace):
    /// - <c>full-relex</c>: every edit costs a from-scratch session Initialize
    ///   (full re-lex of the document) - the "full re-parse" baseline at lex level.
    /// - <c>incremental</c>: one <see cref="RealTimeParserSession"/>, per-edit
    ///   <see cref="RealTimeParserSession.ApplyEdit"/> - the windowed re-lex +
    ///   tail reuse from issue #144 (the engine's SPI analogue: only the edited
    ///   region is re-lexed once realignment is found).
    ///
    /// Reported per edit: latency median across reps, p50/p95 across the trace,
    /// token-reuse ratio (<see cref="RealTimeParserSession.LastReuseRatio"/>) per
    /// edit type, cold-start ratio (mean of first 20 edits / mean of the rest),
    /// allocation per edit, a log-log latency-vs-size fit (tests the article's
    /// "approximately O(log n)" claim), and a parse-time table
    /// (<see cref="RealTimeParserSession.Parse"/>) per file size, capped at
    /// MaxParseSizeLines because GLR parse memory grows steeply with token count.
    /// Tree-sitter is
    /// not available on .NET in CI; that comparison column stays an
    /// external-baseline item, documented in docs/measurements/issue-101/.
    /// </summary>
    public static class Issue101Measurement
    {
        // CI overrides with ISSUE101_SIZES=100,500,2000 to keep the job fast;
        // the default covers all four article sizes (add 5000 back locally).
        private static readonly int[] Sizes = ParseSizes(
            Environment.GetEnvironmentVariable("ISSUE101_SIZES") ?? "100,500,2000,5000");

        private static int[] ParseSizes(string csv) =>
            csv.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
               .Select(int.Parse).ToArray();
        private static readonly string[] TraceNames = { "char-insert", "word-completion", "line-insert", "block-paste" };
        private const int RepsFullRelex = 3;
        private const int RepsIncremental = 10;
        private const int ColdStartEdits = 20;
        // GLR parse memory/time grows steeply with token count (docs/BENCHMARKING.md),
        // so Parse() is measured up to MaxParseSizeLines only; CI lowers it via
        // ISSUE101_MAX_PARSE_LINES. Lex-level per-edit numbers still cover all sizes.
        private static readonly int MaxParseSizeLines =
            int.TryParse(Environment.GetEnvironmentVariable("ISSUE101_MAX_PARSE_LINES"), out var cap)
                ? cap : 500;

        private sealed record Edit(int Offset, int DeleteLength, string InsertText);

        private sealed record ParseRow(int SizeLines, int Tokens, double LexMs, double ParseMs, bool ParseSuccess, int Errors);

        private sealed record FitPoint(int SizeLines, double IncrP50ApplyMs);

        private sealed record CellResult(
            int Size, string Trace, string Config,
            double P50ApplyMs, double P95ApplyMs, double MeanApplyMs,
            double MeanReuseRatio, double ColdStartRatio, double AllocBytesPerEdit);

        /// <summary>Run the measurement and write results into <paramref name="outDir"/>.</summary>
        public static int Run(string outDir)
        {
            Directory.CreateDirectory(outDir);
            var corpusDir = Path.Combine(AppContext.BaseDirectory, "Corpus", "issue-101");
            var grammar = TestGrammars.Get("programming-languages/csharp10/CSharp10.grammar");

            var cells = new List<CellResult>();
            var perEditRows = new List<string>();
            var parseRows = new List<ParseRow>();
            var sizeFit = new List<FitPoint>();

            foreach (var size in Sizes)
            {
                var text0 = File.ReadAllText(Path.Combine(corpusDir, $"cs-{size}.txt"));

                // Parse-time table: one full parse per size (bounded by MaxParseSizeLines).
                if (size <= MaxParseSizeLines)
                {
                    var session = new RealTimeParserSession(grammar, $"cs-{size}.txt")
                    {
                        // Greedy mode: deterministic, linear lexing (the mode all
                        // engine-verified grammar pins run in). The Exploratory
                        // default forks a path per overlapping rule and is
                        // multiplicative on real grammars (issue #142).
                        LexingMode = LexingMode.GreedyLongestMatch,
                    };
                    var sw = Stopwatch.StartNew();
                    session.Initialize(text0);
                    sw.Stop();
                    var lexMs = sw.Elapsed.TotalMilliseconds;
                    sw.Restart();
                    var result = session.Parse();
                    sw.Stop();
                    parseRows.Add(new ParseRow(size, session.Tokens.Count, lexMs,
                        sw.Elapsed.TotalMilliseconds, result.Success, result.Errors.Count));
                    Console.WriteLine($"[parse] {size} lines: lex {lexMs:F1} ms, parse {sw.Elapsed.TotalMilliseconds:F1} ms, success={result.Success}, tokens={session.Tokens.Count}");
            Console.Out.Flush();
                }

                foreach (var traceName in TraceNames)
                {
                    var edits = JsonSerializer.Deserialize<List<Edit>>(
                        File.ReadAllText(Path.Combine(corpusDir, "traces", $"{traceName}.json")),
                        new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

                    // Full re-lex is O(document) per edit: one rep in CI-scale runs;
                    // local full runs can raise RepsFullRelex/RepsIncremental.
                    var repsFull = size <= 500 ? 2 : 1;
                    var repsIncr = 3;
                    var full = RunCell(grammar, text0, edits, incremental: false, repsFull, size, traceName, "full-relex", perEditRows);
                    var incr = RunCell(grammar, text0, edits, incremental: true, repsIncr, size, traceName, "incremental", perEditRows);
                    cells.Add(full);
                    cells.Add(incr);
                }

                // Log-log fit of incremental per-edit latency vs size (O(log n) test).
                var incrP50 = cells.Where(c => c.Config == "incremental" && c.Size == size)
                    .Select(c => c.P50ApplyMs).ToList();
                if (incrP50.Count > 0)
                {
                    sizeFit.Add(new FitPoint(size, Median(incrP50)));
                }
            }

            WritePerEditCsv(Path.Combine(outDir, "issue-101-edit-latency.csv"), perEditRows);
            WriteSummaryJson(Path.Combine(outDir, "issue-101-summary.json"), cells, parseRows, sizeFit);
            WriteMarkdown(Path.Combine(outDir, "RESULTS.md"), cells, parseRows, sizeFit);
            return 0;
        }

        private static CellResult RunCell(
            string grammar, string text0, List<Edit> edits, bool incremental, int reps,
            int size, string traceName, string config, List<string> perEditRows)
        {
            var applySamples = edits.Select(_ => new List<double>()).ToList();
            var reuseSamples = new List<double>();
            long allocPerEdit = 0;

            for (var rep = 0; rep < reps; rep++)
            {
                var text = text0;
                RealTimeParserSession? session = null;
                if (incremental)
                {
                    session = new RealTimeParserSession(grammar, $"cs-{size}.txt")
                    {
                        LexingMode = LexingMode.GreedyLongestMatch,
                    };
                    session.Initialize(text);
                }

                var allocBefore = GC.GetAllocatedBytesForCurrentThread();
                for (var i = 0; i < edits.Count; i++)
                {
                    var e = edits[i];
                    var offset = Math.Min(e.Offset, text.Length);
                    var deleteLength = Math.Min(e.DeleteLength, text.Length - offset);
                    // The text splice itself is untimed in both configs; only the
                    // engine operation (incremental ApplyEdit vs full re-lex) is timed.
                    var newText = text.Substring(0, offset) + e.InsertText + text.Substring(offset + deleteLength);

                    var sw = Stopwatch.StartNew();
                    if (incremental)
                    {
                        session!.ApplyEdit(offset, deleteLength, e.InsertText);
                        reuseSamples.Add(session!.LastReuseRatio);
                    }
                    else
                    {
                        // Full re-lex of the edited document (the lex-level cost of
                        // a from-scratch re-parse).
                        var fresh = new RealTimeParserSession(grammar, $"cs-{size}.txt")
                        {
                            LexingMode = LexingMode.GreedyLongestMatch,
                        };
                        fresh.Initialize(newText);
                    }
                    sw.Stop();
                    applySamples[i].Add(sw.Elapsed.TotalMilliseconds);
                    text = newText;
                }
                allocPerEdit = (GC.GetAllocatedBytesForCurrentThread() - allocBefore) / edits.Count;
            }

            var medians = applySamples.Select(Median).ToList();
            foreach (var (i, m) in medians.Select((v, i) => (i, v)))
            {
                perEditRows.Add($"{size},{traceName},{config},{i},{m.ToString("F4", System.Globalization.CultureInfo.InvariantCulture)}");
            }

            var meanReuse = incremental && reuseSamples.Count > 0 ? reuseSamples.Average() : 0.0;
            var cold = Math.Min(ColdStartEdits, medians.Count);
            var coldMean = medians.Take(cold).Average();
            var restMean = medians.Skip(cold).Count() > 0 ? medians.Skip(cold).Average() : coldMean;
            var coldStartRatio = restMean > 0 ? coldMean / restMean : 1.0;

            var result = new CellResult(size, traceName, config,
                Percentile(medians, 0.50), Percentile(medians, 0.95), medians.Average(),
                meanReuse, coldStartRatio, allocPerEdit);
            Console.WriteLine($"[{config}] {size} lines, {traceName}: p50 {result.P50ApplyMs:F3} ms, p95 {result.P95ApplyMs:F3} ms, " +
                              $"reuse {meanReuse:F2}, cold-start x{coldStartRatio:F2}, alloc/edit {allocPerEdit} B");
            Console.Out.Flush();
            return result;
        }

        private static double Median(List<double> values)
        {
            var sorted = values.OrderBy(v => v).ToList();
            return sorted.Count % 2 == 1
                ? sorted[sorted.Count / 2]
                : (sorted[sorted.Count / 2 - 1] + sorted[sorted.Count / 2]) / 2.0;
        }

        private static double Percentile(List<double> values, double p)
        {
            var sorted = values.OrderBy(v => v).ToList();
            if (sorted.Count == 0)
            {
                return 0;
            }
            var rank = p * (sorted.Count - 1);
            var lo = (int)Math.Floor(rank);
            var hi = (int)Math.Ceiling(rank);
            return lo == hi ? sorted[lo] : sorted[lo] + (sorted[hi] - sorted[lo]) * (rank - lo);
        }

        private static void WritePerEditCsv(string path, List<string> rows)
        {
            var sb = new StringBuilder();
            sb.AppendLine("size_lines,trace,config,edit_index,apply_ms_median");
            foreach (var row in rows)
            {
                sb.AppendLine(row);
            }
            File.WriteAllText(path, sb.ToString());
        }

        private static void WriteSummaryJson(string path, List<CellResult> cells, List<ParseRow> parseRows, List<FitPoint> sizeFit)
        {
            // Log-log slope of incremental p50 vs size (O(log n) claim test).
            var fitPoints = sizeFit.Select(o => new { x = Math.Log(o.SizeLines), y = Math.Log(o.IncrP50ApplyMs) }).ToList();
            double slope = 0;
            if (fitPoints.Count >= 2)
            {
                var mx = fitPoints.Average(p => p.x);
                var my = fitPoints.Average(p => p.y);
                var num = fitPoints.Sum(p => (p.x - mx) * (p.y - my));
                var den = fitPoints.Sum(p => (p.x - mx) * (p.x - mx));
                slope = den > 0 ? num / den : 0;
            }

            var doc = new
            {
                issue = "ENFAStepLexer-StepParser#101",
                measuredUtc = DateTimeOffset.UtcNow.ToString("o"),
                environment = new
                {
                    framework = RuntimeInformation.FrameworkDescription,
                    os = RuntimeInformation.OSDescription,
                    architecture = RuntimeInformation.ProcessArchitecture.ToString(),
                    processorCount = Environment.ProcessorCount,
                },
                method = new
                {
                    grammar = "Minotaur-Grammars@main programming-languages/csharp10/CSharp10.grammar via TestGrammars",
                    corpus = "Corpus/issue-101/cs-{100,500,2000,5000}.txt (committed, gen_corpus.py)",
                    traces = "Corpus/issue-101/traces/*.json (committed, 40 edits each)",
                    repsFullRelex = RepsFullRelex,
                    repsIncremental = RepsIncremental,
                    coldStartEdits = ColdStartEdits,
                    maxParseSizeLines = MaxParseSizeLines,
                    configs = new[]
                    {
                        "full-relex: per edit a fresh session Initialize (full document re-lex)",
                        "incremental: one RealTimeParserSession, per-edit ApplyEdit (windowed re-lex + tail reuse, issue #144)",
                    },
                    treeSitter = "not measurable in this environment (.NET CI runner has no tree-sitter); external-baseline item",
                },
                cells = cells.Select(c => new
                {
                    sizeLines = c.Size,
                    trace = c.Trace,
                    config = c.Config,
                    p50ApplyMs = c.P50ApplyMs,
                    p95ApplyMs = c.P95ApplyMs,
                    meanApplyMs = c.MeanApplyMs,
                    meanReuseRatio = c.MeanReuseRatio,
                    coldStartRatio = c.ColdStartRatio,
                    allocBytesPerEdit = c.AllocBytesPerEdit,
                }),
                parseTable = parseRows,
                sizeFit = new { logLogSlope_incrementalP50_vs_lines = slope, note = "slope ~1 => linear in size; ~0 => constant; O(log n) would show sub-linear growth (slope < 1, shrinking)" },
            };
            File.WriteAllText(path, JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true }));
        }

        private static void WriteMarkdown(string path, List<CellResult> cells, List<ParseRow> parseRows, List<FitPoint> sizeFit)
        {
            var sb = new StringBuilder();
            sb.AppendLine("# Issue #101 measurement: incremental edit latency (lex level) + parse-time table");
            sb.AppendLine();
            sb.AppendLine($"Measured (UTC): {DateTimeOffset.UtcNow:o}; {RuntimeInformation.FrameworkDescription} on {RuntimeInformation.OSDescription} ({RuntimeInformation.ProcessArchitecture}), {Environment.ProcessorCount} cores.");
            sb.AppendLine($"Corpus: committed `Corpus/issue-101/cs-*.txt`, CSharp10 grammar from Minotaur-Grammars@main; traces: committed `traces/*.json` (40 edits each). Reps: full-relex {RepsFullRelex}, incremental {RepsIncremental}.");
            sb.AppendLine();
            sb.AppendLine("## Per-edit lex latency (median across reps, then p50/p95 across the 40-edit trace)");
            sb.AppendLine();
            sb.AppendLine("| Lines | Trace | Config | p50 (ms) | p95 (ms) | mean reuse | cold-start x | alloc/edit (B) |");
            sb.AppendLine("|---|---|---|---|---|---|---|---|");
            foreach (var c in cells)
            {
                sb.AppendLine($"| {c.Size} | {c.Trace} | {c.Config} | {c.P50ApplyMs:F3} | {c.P95ApplyMs:F3} | {c.MeanReuseRatio:F2} | {c.ColdStartRatio:F2} | {(long)c.AllocBytesPerEdit} |");
            }
            sb.AppendLine();
            sb.AppendLine("## Parse-time table (one full parse per size; parse skipped above 2000 lines in CI to bound GLR memory)");
            sb.AppendLine();
            sb.AppendLine("| Lines | Tokens | Lex (ms) | Parse (ms) | Success | Errors |");
            sb.AppendLine("|---|---|---|---|---|---|");
            foreach (var p in parseRows)
            {
                sb.AppendLine($"| {p.SizeLines} | {p.Tokens} | {p.LexMs:F1} | {p.ParseMs:F1} | {p.ParseSuccess} | {p.Errors} |");
            }
            sb.AppendLine();
            sb.AppendLine("## Size scaling (incremental p50 vs lines, log-log slope; 1.0 = linear, O(log n) would be well below 1 and shrinking)");
            sb.AppendLine();
            foreach (var f in sizeFit)
            {
                sb.AppendLine($"- {f.SizeLines} lines: incremental p50 {f.IncrP50ApplyMs:F3} ms");
            }
            sb.AppendLine();
            sb.AppendLine("Tree-sitter comparison is not measurable on the .NET CI runner (no tree-sitter binding); that article column remains an external-baseline item.");
            File.WriteAllText(path, sb.ToString());
        }
    }
}
